( e => {
const { [ 'id' ]: translations } = {"id":{"dictionary":{"Copy selected content":"Salin konten yang dipilih","Paste content":"Tempelkan konten","Paste content as plain text":"Tempelkan konten sebagai teks biasa"}}};
e[ 'id' ] ||= { dictionary: {}, getPluralForm: null };
e[ 'id' ].dictionary = Object.assign( e[ 'id' ].dictionary, translations.dictionary );
if ( translations.getPluralForm ) {
e[ 'id' ].getPluralForm = translations.getPluralForm;
}
} )( window.CKEDITOR_TRANSLATIONS ||= {} );
